WITH with_windows AS (SELECT id, customer_id, device, browser, started_at, country, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY country, customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser_2, ROW_NUMBER() OVER (ORDER BY started_at DESC, id ASC) AS row_seq FROM sessions) SELECT CASE WHEN row_seq >= 7 THEN 'LARGE' ELSE 'SMALL' END AS row_seq_tier, customer_id, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, ROUND(AVG(row_seq), 2) AS avg_row_seq, SUM(row_seq) AS total_row_seq, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count, SIZE(COLLECT_SET(country)) AS num_countries, GROUPING_ID() AS grouping_id FROM with_windows GROUP BY CUBE (CASE WHEN row_seq >= 7 THEN 'LARGE' ELSE 'SMALL' END, customer_id) ORDER BY customer_id DESC NULLS FIRST;
